import{_ as s,l as r,o as e,c as i,v as o,p as n,x as t,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"逃逸分析","description":"","frontmatter":{"title":"逃逸分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/escape-analysis.md","filePath":"cs/escape-analysis.md","lastUpdated":1789023840000}'),h={name:"cs/escape-analysis.md"};function A(E,a,_,m,u,f){const l=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="逃逸分析" tabindex="-1">逃逸分析 <a class="header-anchor" href="#逃逸分析" aria-label="Permalink to &quot;逃逸分析&quot;">​</a></h1><div class="epigraph"><p>若对象从不逃出当前函数或线程，则可栈分配、标量替换或去掉同步。分析跟踪指针是否存到堆、返回、或传给未知代码。</p><footer>—— 据 Choi 等 Escape Analysis for Java；Blanchet, Escape Analysis for Object-Oriented Languages；Appel 对照整理</footer></div><p>上一课<a href="/cs/tail-call-opt">尾调用</a>关心帧能否丢掉。缺口是<strong>堆对象的寿命</strong>：<code>new</code> 的结果若只在当前帧用，不必进 GC 堆。逃逸分析（EA）：NoEscape / ArgEscape / GlobalEscape。本课钉 AOT 视角；JIT 里的 EA 后课再加投机。不写 SROA 细节——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指向分析说指向谁；EA 说<strong>指针是否流出</strong>。流出：写入静态域、返回、传入未知函数。未逃逸：可分配在栈、或拆成标量。缺口是<strong>连通与摘要</strong>，不是 TCO。</p><p>Java：未逃逸对象的锁可删（若语言允许）。C：<code>malloc</code> 未逃逸可改 <code>alloca</code> 或寄存器，但 <code>alloca</code> 与 VLA 有栈风险。</p><h3 id="未逃逸不是「没有别名」" tabindex="-1">未逃逸不是「没有别名」 <a class="header-anchor" href="#未逃逸不是「没有别名」" aria-label="Permalink to &quot;未逃逸不是「没有别名」&quot;">​</a></h3><p>函数内两个局部指针仍可别名同一未逃逸对象。EA 不替代别名，只约束寿命与分配位置。</p><p><span class="marginnote">Choi et al. OOPSLA。Blanchet POPL。HotSpot 的 EA 是 JIT 名场景。本课先过程内+简单过程间摘要。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从分配点沿 store/load/参数走。遇未知调用当 GlobalEscape。过程间：形参 ArgEscape 表示只逃到 caller 可见。迭代到不动点。</p>',11)),(e(),n(d,null,{default:t(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALLOC%5B%22%E5%88%86%E9%85%8D%E7%82%B9%22%5D%20--%3E%20FLOW%5B%22%E6%8C%87%E9%92%88%E6%B5%81%22%5D%0A%20%20FLOW%20--%3E%20ESC%5B%22No%20%2F%20Arg%20%2F%20Global%22%5D%0A%20%20ESC%20--%3E%20STK%5B%22%E6%A0%88%E5%8C%96%20%2F%20%E6%A0%87%E9%87%8F%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与<a href="/cs/inlining-heuristics">内联</a>：内联后未知调用变已知，EA 更精。顺序：内联再 EA 常见。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归结构、函数指针、异常路径都要保守。不要把「未逃逸」当可以延长到 TCO 跳转之后——帧没了栈对象也没了。</p><p>多线程：未逃逸到其它线程可去同步；分析错则数据竞争。须可靠。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整连接图算法。后课默认：未逃逸可栈化。下一课 SROA：把聚合拆成标量 SSA 名。</p><p>也不把 EA 当线性类型；线性是语言纪律，EA 是分析。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逃逸分析跟踪指针是否流出函数/线程。</li><li>NoEscape 允许栈分配、去同步、拆标量。</li><li>必须保守；与内联、指向分析配合。</li><li>出处：Choi et al.；Blanchet；对照 Appel 堆栈决策。</li></ul>',9))])}const C=s(h,[["render",A]]);export{b as __pageData,C as default};
